   202  static int ftp_pl_get_permission(const char *str)
   203  {
   204    int permissions = 0;
   205    /* USER */
   206    if(str[0] == 'r')
   207      permissions |= 1 << 8;
   208    else if(str[0] != '-')
   209      permissions |= FTP_LP_MALFORMATED_PERM;
   210    if(str[1] == 'w')
   211      permissions |= 1 << 7;
   212    else if(str[1] != '-')
   213      permissions |= FTP_LP_MALFORMATED_PERM;
   214
   215    if(str[2] == 'x')
   216      permissions |= 1 << 6;
   217    else if(str[2] == 's') {
   218      permissions |= 1 << 6;
   219      permissions |= 1 << 11;
   220    }
   221    else if(str[2] == 'S')
   222      permissions |= 1 << 11;
   223    else if(str[2] != '-')
   224      permissions |= FTP_LP_MALFORMATED_PERM;
   225    /* GROUP */
   226    if(str[3] == 'r')
   227      permissions |= 1 << 5;
   228    else if(str[3] != '-')
   229      permissions |= FTP_LP_MALFORMATED_PERM;
   230    if(str[4] == 'w')
   231      permissions |= 1 << 4;
   232    else if(str[4] != '-')
   233      permissions |= FTP_LP_MALFORMATED_PERM;
   234    if(str[5] == 'x')
   235      permissions |= 1 << 3;
   236    else if(str[5] == 's') {
   237      permissions |= 1 << 3;
   238      permissions |= 1 << 10;
   239    }
   240    else if(str[5] == 'S')
   241      permissions |= 1 << 10;
   242    else if(str[5] != '-')
   243      permissions |= FTP_LP_MALFORMATED_PERM;
   244    /* others */
   245    if(str[6] == 'r')
   246      permissions |= 1 << 2;
   247    else if(str[6] != '-')
   248      permissions |= FTP_LP_MALFORMATED_PERM;
   249    if(str[7] == 'w')
   250      permissions |= 1 << 1;
   251    else if(str[7] != '-')
   252        permissions |= FTP_LP_MALFORMATED_PERM;
   253    if(str[8] == 'x')
   254      permissions |= 1;
   255    else if(str[8] == 't') {
   256      permissions |= 1;
   257      permissions |= 1 << 9;
   258    }
   259    else if(str[8] == 'T')
   260      permissions |= 1 << 9;
   261    else if(str[8] != '-')
   262      permissions |= FTP_LP_MALFORMATED_PERM;
   263
   264    return permissions;
   265  }
